// Node-RED manda: { tipo, sensor, valor, umbral, mensaje, fecha, modo, actuadores }
const a = $input.first().json.body;
const d = new Date(new Date(a.fecha).getTime() - 3 * 3600 * 1000);   // hora de Argentina (UTC-3)
const dos = n => String(n).padStart(2, '0');
const hora = `${dos(d.getUTCDate())}/${dos(d.getUTCMonth() + 1)} ${dos(d.getUTCHours())}:${dos(d.getUTCMinutes())} h`;
const act = a.actuadores || {};

const texto = [
  '🌱 Invernadero IoT — ALERTA',
  '',
  a.mensaje,
  '',
  `🕒 ${hora}`,
  `⚙️ Modo: ${a.modo === 'manual' ? 'manual' : 'automático'}`,
  `💧 Riego: ${act.riego || '-'}   🌀 Ventilador: ${act.ventilador || '-'}`
].join('\n');

return [{ json: { texto, tipo: a.tipo } }];

// Respuesta de GET /invernadero/resumen (Node-RED)
const r = $input.first().json;
const s = r.sensores || {};
const linea = (nombre, clave, unidad) => s[clave]
  ? `${nombre}: mín ${s[clave].minimo}${unidad} · máx ${s[clave].maximo}${unidad} · prom ${s[clave].promedio}${unidad}`
  : `${nombre}: sin datos`;

const texto = [
  '🌱 Invernadero IoT — Resumen de las últimas 24 h',
  '',
  linea('🌡️ Temperatura', 'temperatura', ' °C'),
  linea('💨 Humedad ambiente', 'humedad_ambiente', ' %'),
  linea('🪴 Humedad del suelo', 'humedad_suelo', ' %'),
  linea('☀️ Luz', 'luz', ' lx'),
  '',
  `💧 Riegos: ${r.encendidos?.riego ?? 0}   🌀 Ventilaciones: ${r.encendidos?.ventilador ?? 0}`,
  `🚨 Alertas: ${r.alertas ?? 0}`
].join('\n');

return [{ json: { texto } }];
